function mediaId(value){
 const s=String(value||'').trim();if(/^[\w-]{11}$/.test(s))return s;
 try{const u=new URL(s);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.port)return null;const host=u.hostname.replace(/^www\./,'');
 if(host==='soundcloud.com'&&/^\/[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+\/?$/.test(u.pathname)&&!/^\/(?:discover|you|search|charts|sets)\//.test(u.pathname))return 'https://soundcloud.com'+u.pathname.replace(/\/$/,'');
 const id=host==='youtu.be'?u.pathname.slice(1):['youtube.com','m.youtube.com','music.youtube.com'].includes(host)?u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed|live)\/([\w-]{11})/)?.[1]:null;return /^[\w-]{11}$/.test(id||'')?id:null;
 }catch{return null}
}
function mediaUrl(id){return String(id).startsWith('https://soundcloud.com/')?id:'https://www.youtube.com/watch?v='+id}

const CLIENT_ID="266490964078-ac8nl0rs22l9ku74idb5e59umi5h9j3d.apps.googleusercontent.com";
const BETA_ORIGINS=new Set(['https://beta.dkplaylist.com','https://dkplaylist-beta.dk-music.workers.dev']);
const ORIGINS=new Set(['https://dkplaylist.dk-music.workers.dev','https://dkplaylist.com','https://www.dkplaylist.com']);
