// Public catalog only. Bump this when changing catalog projection/corrections.
const CATALOG_CACHE_VERSION='2026-10-27-v1';
const CATALOG_EDGE_SECONDS=60;
function catalogCacheKey(origin){return new Request(origin+'/api/catalog?__cache='+CATALOG_CACHE_VERSION)}
function etagMatches(req,etag){return (req.headers.get('if-none-match')||'').split(',').some(v=>v.trim()==='*'||v.trim().replace(/^W\//,'')===etag.replace(/^W\//,''))}
async function cacheValidator(req,response,policy){
 const text=await response.text();
 const headers=new Headers(response.headers);
 const etag='"'+await sessionHash(text)+'"';
 headers.set('ETag',etag);headers.set('Cache-Control',policy);
 if(etagMatches(req,etag))return new Response(null,{status:304,headers});
 return new Response(req.method==='HEAD'?null:text,{status:response.status,headers});
}
async function invalidateCatalogCache(){
 if(typeof caches==='undefined')return;
 // Production and beta share D1. Deletion is local to this Cloudflare location;
 // other locations expire within 60s. The editing browser explicitly bypasses cache.
 await Promise.all([...ORIGINS,...BETA_ORIGINS].map(async origin=>{
  try{await caches.default.delete(catalogCacheKey(origin))}catch{console.warn('catalog cache invalidation failed')}
 }));
}
async function cachedApi(req,env,url,ctx){
 if(req.method!=='GET'||url.pathname!=='/api/catalog'){
  const response=await api(req,env,url);
  if(req.method==='POST'&&response.ok&&['/api/recommend','/api/admin'].includes(url.pathname))await invalidateCatalogCache();
  return response;
 }
 const startedAt=Date.now();
 const bypass=/no-cache|no-store|max-age=0/i.test(req.headers.get('cache-control')||'');
 const cache=typeof caches==='undefined'?null:caches.default;
 const key=catalogCacheKey(url.origin);
 let response;
 if(cache&&!bypass){try{response=await cache.match(key)}catch{console.warn('catalog cache read failed')}}
 if(response&&Date.now()-Number(response.headers.get('X-DK-Cached-At')||0)>=CATALOG_EDGE_SECONDS*1000)response=null;
 const hit=!!response;
 if(!response){
  response=await api(req,env,url);
  if(response.status!==200||response.headers.has('set-cookie'))return response;
  // Hash once on fill, not for every visitor. No incoming cookies enter the key.
  const text=await response.text(),headers=new Headers(response.headers);
  headers.set('ETag','W/"'+await sessionHash(text)+'"');
  headers.set('Cache-Control','public, max-age='+CATALOG_EDGE_SECONDS);
  headers.set('X-DK-Cached-At',String(startedAt));
  response=new Response(text,{headers});
  if(cache){
   const write=cache.put(key,response.clone()).catch(()=>console.warn('catalog cache write failed'));
   if(ctx?.waitUntil)ctx.waitUntil(write);else await write;
  }
 }
 const headers=new Headers(response.headers);
 // Keep downstream shared caches out of the mutation invalidation contract.
 // Browser revalidation can return 304 without reading D1 on an edge hit.
 headers.set('Cache-Control','private, max-age=0, must-revalidate');
 headers.set('X-DK-Cache',bypass?'BYPASS':hit?'HIT':'MISS');
 headers.set('X-DK-Catalog-TTL',String(Math.max(0,Math.min(30,Math.floor((Number(headers.get('X-DK-Cached-At'))+CATALOG_EDGE_SECONDS*1000-Date.now())/1000)))));
 headers.delete('X-DK-Cached-At');headers.delete('age');
 if(etagMatches(req,headers.get('etag')))return new Response(null,{status:304,headers});
 return new Response(response.body,{headers});
}

